    let mut file=std::fs::OpenOptions::new().create_new(true).write(true).open(&args[1])?;file.write_all(&serde_json::to_vec_pretty(&report)?)?;file.sync_all()?;println!("native physique tuning={} candidates={} pins={} ordered-jobs={} originals-unchanged=true",selected.tuning.source.key,result.candidates.len(),result.source_pins.len(),selected.weights.ordered.len());Ok(())
